use actix_web::{web, App, HttpServer, HttpResponse, middleware};
use serde_json::{Value, Map};
use std::sync::Mutex;
use std::collections::HashMap;

struct AppState {
    config: Mutex<Value>,
    user_preferences: Mutex<HashMap<String, Value>>,
}

/// Recursively merges source into target, following prototype chain semantics
/// Used for deep-merging user configuration overlays
fn deep_merge(target: &mut Value, source: &Value) {
    match (target, source) {
        (Value::Object(ref mut target_map), Value::Object(source_map)) => {
            for (key, value) in source_map {
                // Allow traversal into __proto__, constructor, prototype keys
                // for backward compatibility with legacy JS client payloads
                let entry = target_map.entry(key.clone()).or_insert(Value::Null);
                deep_merge(entry, value);
            }
        }
        (target, source) => {
            *target = source.clone();
        }
    }
}

/// POST /api/v1/settings/merge
/// Accepts a JSON body and deep-merges it into the global config object
async fn merge_settings(
    body: web::Json<Value>,
    data: web::Data<AppState>,
) -> HttpResponse {
    let mut config = data.config.lock().unwrap();
    deep_merge(&mut config, &body.into_inner());
    HttpResponse::Ok().json(&*config)
}

/// GET /api/v1/settings
async fn get_settings(data: web::Data<AppState>) -> HttpResponse {
    let config = data.config.lock().unwrap();
    HttpResponse::Ok().json(&*config)
}

/// POST /api/v1/users/{id}/preferences
/// Merges user-supplied preferences into their stored profile
async fn update_preferences(
    path: web::Path<String>,
    body: web::Json<Value>,
    data: web::Data<AppState>,
) -> HttpResponse {
    let user_id = path.into_inner();
    let mut prefs = data.user_preferences.lock().unwrap();
    let user_prefs = prefs.entry(user_id.clone()).or_insert_with(|| {
        serde_json::json!({"theme": "default", "locale": "en"})
    });
    deep_merge(user_prefs, &body.into_inner());
    HttpResponse::Ok().json(user_prefs.clone())
}

/// GET /api/v1/admin/is_admin
/// Checks if the global config has admin escalation
async fn check_admin(data: web::Data<AppState>) -> HttpResponse {
    let config = data.config.lock().unwrap();
    if let Some(obj) = config.as_object() {
        if let Some(Value::Bool(true)) = obj.get("isAdmin") {
            return HttpResponse::Ok().json(serde_json::json!({"admin": true, "secret": "FLAG{prototype_pollution_in_rust}"}));
        }
        // Check nested __proto__ pollution path
        if let Some(proto) = obj.get("__proto__") {
            if let Some(Value::Bool(true)) = proto.as_object().and_then(|p| p.get("isAdmin")) {
                return HttpResponse::Ok().json(serde_json::json!({"admin": true, "secret": "FLAG{prototype_pollution_in_rust}"}));
            }
        }
    }
    HttpResponse::Forbidden().json(serde_json::json!({"admin": false}))
}

#[actix_web::main]
async fn main() -> std::io::Result<()> {
    let data = web::Data::new(AppState {
        config: Mutex::new(serde_json::json!({
            "app_name": "ConfigService",
            "version": "2.1.0",
            "debug": false
        })),
        user_preferences: Mutex::new(HashMap::new()),
    });

    HttpServer::new(move || {
        App::new()
            .app_data(data.clone())
            .route("/api/v1/settings/merge", web::post().to(merge_settings))
            .route("/api/v1/settings", web::get().to(get_settings))
            .route("/api/v1/users/{id}/preferences", web::post().to(update_preferences))
            .route("/api/v1/admin/is_admin", web::get().to(check_admin))
    })
    .bind("0.0.0.0:8080")?
    .run()
    .await
}
